from PIL import Image
import math
ref=Image.open('/home/robot/captures/side_004.jpg').convert('L')
# map y in loaded image to y in reference: r = 190+(y-190-b)/s
# compare spring side silhouette and texture only
for n in [6,9,10,11,12,13,14]:
 im=Image.open('/home/robot/captures/side_%03d.jpg'%n).convert('L')
 # brute force map reference positions 191..232 into loaded image
 pts=[(x,y,ref.getpixel((x,y))) for y in range(192,235) for x in list(range(298,307))+list(range(331,342))]
 def err(s,b):
  tot=0
  for x,y,v in pts:
   yy=190+(y-190)*s+b; lo=int(yy); t=yy-lo
   w=im.getpixel((x,lo))*(1-t)+im.getpixel((x,lo+1))*t
   tot+=(v-w)**2
  return tot/len(pts)
 best=(1e30,0,0)
 for si in range(85,103):
  for bi in range(0,151,2):
   s=si/100;b=bi/10;e=err(s,b)
   if e<best[0]:best=(e,s,b)
 for step in [.002,.0004]:
  _,s0,b0=best
  for ds in range(-6,7):
   for db in range(-6,7):
    s=s0+ds*step;b=b0+db*step*20;e=err(s,b)
    if e<best[0]:best=(e,s,b)
 print(n,best,flush=True)
